import {savedPreviewsKey} from './saved-model.mjs';
import {showSupportChoices,showSupportMessageStep} from './card-actions.mjs';
import {debtCardHTML,cardDetailsHTML} from './debt-card.mjs';
let previewSkipped=false,previewSaved=false;let draftCardId=crypto.randomUUID();
import {defaultPrivacy,validateDetails,publicCard} from './card-model.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let api,identity={},step=1,debts=[{title:'',story:'',amount:''}],privacy=defaultPrivacy(),submitted=false;
const options=[['realName','Show my real name','Hiển thị họ tên thật trên thẻ.'],['age','Show my age','Hiển thị tuổi của bạn nếu đã cung cấp.'],['location','Show my Location','Hiển thị địa điểm nếu bạn đã cung cấp.'],['photo','Show my profile photo','Hiển thị ảnh đại diện nếu đã có.'],['publicStory','Show my story to the public','Cho phép câu chuyện của bạn xuất hiện trên bản xem công khai.']];
export function initCardWizard(callbacks){api=callbacks;const root=document.createElement('section');root.id='card-wizard';document.body.append(root);root.addEventListener('input',event=>{const field=event.target;if(field.dataset.field)debts[Number(field.dataset.index)][field.dataset.field]=field.dataset.field==='amount'?(field.value===''?'':Number(field.value)):field.value;});root.addEventListener('change',event=>{if(event.target.dataset.privacy){privacy[event.target.dataset.privacy]=event.target.checked;const label=event.target.closest('.cw-switch').querySelector('.cw-switch-state');label.textContent=event.target.checked?'On':'Off';}});root.addEventListener('click',event=>{const b=event.target.closest('[data-cw]');if(!b||submitting)return;switch(b.dataset.cw){case 'restore-card':previewSkipped=false;render();break;case 'back':if(submitted){document.body.classList.remove('card-wizard-mode');api.profile();return;}else if(step>1)step--;else{document.body.classList.remove('card-wizard-mode');api.back();return;}render();break;case 'next':if(step===1){try{debts=validateDetails(debts);}catch(error){errorMessage(error.message);return;}}step=Math.min(3,step+1);render();break;case 'add':if(debts.length>=20){errorMessage('Bạn có thể thêm tối đa 20 khoản nợ.');return;}debts.push({title:'',story:'',amount:''});render();document.querySelector(`[data-index="${debts.length-1}"]`)?.focus();break;case 'remove':debts.splice(Number(b.dataset.index),1);render();break;case 'step':{const target=Number(b.dataset.step);if(!submitted&&target<step){step=target;render();}break;}case 'submit':submit();break;case 'new':previewSaved=false;previewSkipped=false;draftCardId=crypto.randomUUID();debts=[{title:'',story:'',amount:''}];privacy=defaultPrivacy();step=1;submitted=false;render();break;case 'profile':document.body.classList.remove('card-wizard-mode');api.profile();break;case 'debts':document.body.classList.remove('card-wizard-mode');api.debts();break;}});}
export function showCardWizard(user){identity={...user,nickname:user?.nickname||(user?.designPreview?'Broke_Studio':'Broke_'+(user?.id||'preview').slice(0,6))};previewSkipped=false;document.body.classList.remove('onboarding','registration-mode','broke-mode','debts-mode','messages-mode','bros-join-mode');document.body.classList.add('card-wizard-mode');render();window.scrollTo(0,0);}
function errorMessage(message){const field=document.querySelector('#cw-error');if(field){field.textContent=message;field.focus();}}
function render(){const root=document.querySelector('#card-wizard');root.innerHTML=`<div class="cw-shell"><div class="cw-header"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"><a href="/my-cards" class="cw-status-link">Thẻ đã gửi</a><button data-cw="${step===1&&!submitted?'profile':'back'}">← ${step===1&&!submitted?'Trang cá nhân':'Quay lại'}</button></div><div class="cw-intro"><span>YOUR NEXT CHAPTER STARTS HERE</span><h1>Create Your Debt Card</h1><p>Một câu chuyện chân thành. Một cơ hội để cùng nhau bước tiếp.</p></div><ol class="cw-progress" aria-label="Các bước tạo thẻ">${['Detail','Privacy','Review Card'].map((label,index)=>`<li class="${step===index+1&&!submitted?'current':step>index+1||submitted?'complete':''}" ${step===index+1&&!submitted?'aria-current="step"':''}><button data-cw="step" data-step="${index+1}" ${submitted||index+1>=step?'disabled':''}><b>${step>index+1||submitted?'✓':index+1}</b><span>${label}</span></button></li>`).join('')}</ol><div class="cw-content">${submitted?successView():step===1?detailsView():step===2?privacyView():reviewView()}</div>${submitted?'':`<div id="cw-error" class="cw-error" tabindex="-1" role="alert"></div><div class="cw-navigation"><button class="cw-back" data-cw="back">← ${step===1?'Quay lại':'Bước trước'}</button><span>Bước ${step} / 3</span><button class="cw-next" data-cw="${step===3?'submit':'next'}">${step===3?'Submit':'Tiếp tục'} <span>→</span></button></div>`}<p class="cw-storage">Thẻ Submit được gửi đến admin xét duyệt. Nội dung chưa gửi chỉ được giữ trong phiên này.</p></div>`;}
function detailsView(){return `<div class="cw-section-heading"><h2>Debt Details</h2><p>Bạn có thể thêm nhiều hơn một khoản nợ bằng cách chọn dấu + bên dưới.</p></div><div class="cw-debt-groups">${debts.map((debt,index)=>`<section class="cw-debt-group"><div class="cw-group-header"><span>KHOẢN NỢ ${String(index+1).padStart(2,'0')}</span>${debts.length>1?`<button data-cw="remove" data-index="${index}" aria-label="Xóa khoản nợ ${index+1}">×</button>`:''}</div><label for="cw-title-${index}">Title <span>*</span></label><p class="cw-field-help">Tiêu đề tóm tắt khoản nợ của bạn, hiển thị trên thẻ.</p><input id="cw-title-${index}" data-field="title" data-index="${index}" maxlength="100" required placeholder="Ví dụ: Một khoảng thở để hoàn thành năm học cuối" value="${esc(debt.title)}"><label for="cw-amount-${index}">Số tiền nợ (VNĐ) <span>*</span></label><p class="cw-field-help">Số tiền hiện còn nợ của khoản này.</p><input id="cw-amount-${index}" data-field="amount" data-index="${index}" type="number" inputmode="numeric" min="1" max="1000000000000" step="1" required placeholder="Ví dụ: 14000000" value="${esc(debt.amount)}"><label for="cw-story-${index}">Your story <span>*</span></label><p class="cw-field-help">Vì sao bạn có khoản nợ này? Chia sẻ để Bros hiểu hơn về câu chuyện của bạn.</p><textarea id="cw-story-${index}" data-field="story" data-index="${index}" maxlength="3000" required placeholder="Hãy kể câu chuyện của bạn bằng lời của chính mình…">${esc(debt.story)}</textarea><small>Tối đa 3.000 ký tự. Tránh ghi thông tin thẻ, số tài khoản hoặc giấy tờ cá nhân.</small></section>`).join('')}</div><button class="cw-add" data-cw="add" ${debts.length>=20?'disabled':''}><b>＋</b> Thêm khoản nợ</button>`;}
function privacyView(){return `<div class="cw-section-heading"><h2>Privacy & Display</h2><p>Bạn quyết định những gì người khác nhìn thấy trên thẻ của mình.</p></div><div class="cw-privacy-list">${options.map(([key,label,description])=>`<div class="cw-privacy-row"><div><label for="cw-privacy-${key}">${label}</label><p>${description}</p></div><label class="cw-switch"><input id="cw-privacy-${key}" type="checkbox" role="switch" data-privacy="${key}" ${privacy[key]?'checked':''}><span class="cw-switch-track"></span><span class="cw-switch-state">${privacy[key]?'On':'Off'}</span></label></div>`).join('')}</div><div class="cw-privacy-note">♧ Các mục mặc định ở trạng thái Off. Nếu chưa có tuổi, địa điểm hoặc ảnh đại diện, thẻ sẽ không tự điền thông tin thay bạn.</div>`;}
function preview(){try{previewSaved=Boolean(JSON.parse(localStorage.getItem(savedPreviewsKey(identity.id||'device-preview'))||'{}')[draftCardId]);}catch{}const card=publicCard(debts,privacy,identity);return previewSkipped?'<div class="df-skipped"><h3>Đã bỏ qua thẻ xem trước.</h3><p>Thao tác này không xóa nội dung thẻ của bạn.</p><button data-cw="restore-card">↶ Xem lại thẻ</button></div>':debtCardHTML(card,{saved:previewSaved,id:draftCardId});}
function reviewView(){return `<div class="cw-section-heading"><h2>Review Card</h2><p>Đây là bản xem trước nội dung Bros sẽ thấy, theo các lựa chọn riêng tư của bạn.</p></div><div class="cw-review-layout">${preview()}<aside class="cw-review-note"><span>♧</span><h3>Your story. Your choice.</h3><p>Kiểm tra lại tiêu đề, câu chuyện và thông tin hiển thị trước khi Submit.</p><p>Bạn đã thêm <strong>${debts.length} khoản nợ</strong>.</p><button data-cw="back">Chỉnh lại quyền riêng tư ←</button></aside></div>`;}
let submitting=false;
async function submit(){if(submitting)return;try{debts=validateDetails(debts);submitting=true;const button=document.querySelector('[data-cw="submit"]');if(button){button.disabled=true;button.textContent='Đang gửi…';}const response=await fetch('/api/cards',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({submissionId:draftCardId,debts,privacy})});const result=await response.json();if(!response.ok)throw Error(result.error||'Không thể gửi thẻ.');submitted=true;render();document.querySelector('#cw-success-title')?.focus();}catch(error){errorMessage(error.message||'Không thể gửi thẻ. Nội dung của bạn vẫn được giữ lại.');const button=document.querySelector('[data-cw="submit"]');if(button){button.disabled=false;button.textContent='Submit →';}}finally{submitting=false;}}
function successView(){return `<div class="cw-success"><div class="cw-success-check">✓</div><h2 id="cw-success-title" tabindex="-1">Submit thành công</h2><p>Debt Card đã được gửi đến admin và đang chờ duyệt.<br>Chỉ sau khi được duyệt, thẻ mới xuất hiện trong trang quẹt.</p><div class="cw-success-actions"><a class="cw-next" href="/my-cards">Xem trạng thái thẻ</a><button class="cw-next" data-cw="profile">Về trang cá nhân →</button><button class="cw-back" data-cw="new">＋ Tạo thẻ mới</button></div></div><div class="cw-success-preview">${preview()}</div>`;}
document.addEventListener('click',event=>{const button=event.target.closest('#card-wizard [data-dc]');if(!button)return;const card=publicCard(debts,privacy,identity);if(button.dataset.dc==='skip'){previewSkipped=true;render();}if(button.dataset.dc==='detail')showSupportChoices({modal:api.modal,close:api.close,pay:()=>showSupportMessageStep({id:'preview:'+draftCardId,name:card.name,modal:api.modal,toast:api.toast}),contact:()=>api.contact({id:'preview:'+draftCardId,name:card.name,title:card.debts.map(d=>d.title).join(' · ')})});if(button.dataset.dc==='save'){try{const key=savedPreviewsKey(identity.id||'device-preview'),saved=JSON.parse(localStorage.getItem(key)||'{}');if(previewSaved)delete saved[draftCardId];else saved[draftCardId]=card;localStorage.setItem(key,JSON.stringify(saved));previewSaved=!previewSaved;render();api.toast(previewSaved?'Đã lưu thẻ xem trước trên thiết bị.':'Đã bỏ lưu thẻ xem trước.');}catch{api.toast('Không thể lưu thẻ trên thiết bị.');}}});


export function startNewDebtCard(user){debts=[{title:'',story:'',amount:''}];privacy=defaultPrivacy();step=1;submitted=false;previewSkipped=false;previewSaved=false;draftCardId=crypto.randomUUID();showCardWizard(user);}


